import * as console from "node:console";
import { randomUUID } from "node:crypto";
import { notNull } from "@allurereport/core-api";
import { XMLParser } from "fast-xml-parser";
import { parseProperties } from "../properties.js";
import { ensureBoolean, ensureInt, ensureString } from "../utils.js";
import { cleanBadXmlCharacters, isStringAnyRecord, isStringAnyRecordArray } from "../xml-utils.js";
import { ParameterMode } from "./model.js";
const arrayTags = new Set(["environment.parameter"]);
const xmlParser = new XMLParser({
    parseTagValue: false,
    ignoreAttributes: false,
    attributeNamePrefix: "",
    removeNSPrefix: true,
    allowBooleanAttributes: true,
    processEntities: false,
    isArray: (tagName, jPath) => arrayTags.has(jPath.toString()),
});
const readerId = "allure2";
const historyMetadataKeys = {
    "history.json": "allure2_history",
    "history-trend.json": "allure2_history_trend",
    "duration-trend.json": "allure2_duration_trend",
    "retry-trend.json": "allure2_retry_trend",
    "categories-trend.json": "allure2_categories_trend",
};
const isAllure2AttachmentFileName = (fileName) => {
    const attachmentIdx = fileName.lastIndexOf("-attachment");
    if (attachmentIdx === -1) {
        return false;
    }
    const suffix = fileName.slice(attachmentIdx + "-attachment".length);
    return suffix === "" || suffix.startsWith(".");
};
const matchesAllure2File = (fileName) => {
    if (fileName.endsWith("-result.json"))
        return true;
    if (fileName.endsWith("-check.json"))
        return true;
    if (fileName.endsWith("-perf.json"))
        return true;
    if (fileName === "performance.json")
        return true;
    if (fileName.endsWith("-container.json"))
        return true;
    if (fileName.endsWith("-globals.json"))
        return true;
    if (isAllure2AttachmentFileName(fileName))
        return true;
    if (fileName === "executor.json")
        return true;
    if (fileName === "categories.json")
        return true;
    if (fileName === "environment.properties")
        return true;
    if (fileName === "environment.xml")
        return true;
    if (fileName in historyMetadataKeys)
        return true;
    return false;
};
export const allure2 = {
    matches: (data) => matchesAllure2File(data.getOriginalFileName()),
    read: async (visitor, data) => {
        const originalFileName = data.getOriginalFileName();
        if (originalFileName.endsWith("-check.json")) {
            try {
                const parsed = await data.asJson();
                if (parsed && isStringAnyRecord(parsed)) {
                    await processCheckResult(visitor, parsed, originalFileName);
                }
                return true;
            }
            catch (e) {
                console.error("error parsing", originalFileName, e);
                return false;
            }
        }
        if (originalFileName.endsWith("-perf.json") || originalFileName === "performance.json") {
            try {
                const results = await data.asJson();
                if (!Array.isArray(results)) {
                    return false;
                }
                await visitor.visitMetrics(results, { readerId, metadata: { originalFileName } });
                return true;
            }
            catch (e) {
                console.error("error parsing", originalFileName, e);
                return false;
            }
        }
        if (originalFileName.endsWith("-result.json")) {
            try {
                const parsed = await data.asJson();
                if (parsed && isStringAnyRecord(parsed)) {
                    await processTestResult(visitor, parsed, originalFileName);
                }
                return true;
            }
            catch (e) {
                console.error("error parsing", originalFileName, e);
                return false;
            }
        }
        if (originalFileName.endsWith("-container.json")) {
            const parsed = await data.asJson();
            if (parsed) {
                await processTestResultContainer(visitor, parsed);
            }
            return true;
        }
        if (originalFileName.endsWith("-globals.json")) {
            const parsed = await data.asJson();
            if (parsed) {
                await processGlobals(visitor, parsed);
            }
            return true;
        }
        const historyMetadataKey = historyMetadataKeys[originalFileName];
        if (historyMetadataKey) {
            try {
                const parsed = await data.asJson();
                if (parsed && (isStringAnyRecord(parsed) || isStringAnyRecordArray(parsed))) {
                    await visitor.visitMetadata({ [historyMetadataKey]: parsed }, { readerId });
                }
                return true;
            }
            catch (e) {
                console.error("error parsing", originalFileName, e);
                return false;
            }
        }
        if (originalFileName === "executor.json") {
            try {
                const parsed = await data.asJson();
                if (parsed && isStringAnyRecord(parsed)) {
                    await processExecutor(visitor, parsed);
                }
                return true;
            }
            catch (e) {
                console.error("error parsing", originalFileName, e);
                return false;
            }
        }
        if (originalFileName === "categories.json") {
            try {
                const parsed = await data.asJson();
                if (parsed && isStringAnyRecordArray(parsed)) {
                    await processCategories(visitor, parsed);
                }
                return true;
            }
            catch (e) {
                console.error("error parsing", originalFileName, e);
                return false;
            }
        }
        if (originalFileName === "environment.properties") {
            try {
                const raw = await data.asUtf8String();
                if (raw) {
                    const parsed = parseProperties(raw);
                    if (parsed && isStringAnyRecord(parsed)) {
                        await processEnvironment(visitor, parsed);
                    }
                }
                return true;
            }
            catch (e) {
                console.error("error parsing", originalFileName, e);
                return false;
            }
        }
        if (originalFileName === "environment.xml") {
            try {
                const asBuffer = await data.asBuffer();
                if (!asBuffer) {
                    return false;
                }
                const content = cleanBadXmlCharacters(asBuffer).toString("utf-8");
                const parsed = xmlParser.parse(content);
                if (isStringAnyRecord(parsed)) {
                    await processEnvironmentXml(visitor, parsed);
                }
                return true;
            }
            catch (e) {
                console.error("error parsing", originalFileName, e);
                return false;
            }
        }
        await visitor.visitAttachmentFile(data, { readerId });
        return true;
    },
    readerId: () => readerId,
};
const processTestResult = async (visitor, result, originalFileName) => {
    const links = result?.links?.filter(notNull) ?? [];
    const topLevelAttachmentCount = result?.attachments?.filter(notNull).length ?? 0;
    const dest = {
        uuid: ensureString(result.uuid),
        titlePath: result?.titlePath?.length ? result.titlePath : [],
        fullName: ensureString(result.fullName),
        name: ensureString(result.name),
        testId: ensureString(result.testCaseId),
        historyId: ensureString(result.historyId),
        start: ensureInt(result.start),
        stop: ensureInt(result.stop),
        description: ensureString(result.description),
        descriptionHtml: ensureString(result.descriptionHtml),
        status: convertStatus(result.status),
        message: ensureString(result?.statusDetails?.message),
        trace: ensureString(result?.statusDetails?.trace),
        actual: ensureString(result?.statusDetails?.actual, ""),
        expected: ensureString(result?.statusDetails?.expected, ""),
        flaky: ensureBoolean(result?.statusDetails?.flaky),
        known: ensureBoolean(result?.statusDetails?.known),
        muted: ensureBoolean(result?.statusDetails?.muted),
        parameters: result?.parameters?.filter(notNull)?.map(convertParameter),
        steps: [
            ...(result?.steps?.filter(notNull)?.map(convertStep) ?? []),
            ...(result?.attachments?.filter(notNull)?.map(convertAttachment) ?? []),
        ],
        links: links.map(convertLink),
        labels: result.labels?.filter(notNull)?.map(convertLabel),
    };
    await visitor.visitTestResult(dest, {
        readerId,
        metadata: {
            originalFileName,
            allure2_links: links,
            allure2_top_level_attachment_count: topLevelAttachmentCount,
        },
    });
};
const processCheckResult = async (visitor, result, originalFileName) => {
    const tags = Array.isArray(result.tags) ? result.tags.map((tag) => ensureString(tag)).filter(notNull) : [];
    const details = isStringAnyRecord(result.details) ? result.details : {};
    const message = ensureString(details.message);
    const error = ensureString(details.error);
    await visitor.visitCheckResult({
        id: ensureString(result.id, ""),
        name: ensureString(result.name, originalFileName.replace(/-check\.json$/, "")),
        status: convertCheckStatus(result.status),
        ...(tags.length ? { tags } : {}),
        details: {
            command: ensureString(details.command, ""),
            ...(message ? { message } : {}),
            ...(error ? { error } : {}),
        },
    }, { readerId, metadata: { originalFileName } });
};
const processExecutor = async (visitor, result) => {
    await visitor.visitMetadata({
        allure2_executor: {
            name: ensureString(result.name),
            type: ensureString(result.type),
            url: ensureString(result.url),
            buildOrder: ensureInt(result.buildOrder),
            buildName: ensureString(result.buildName),
            buildUrl: ensureString(result.buildUrl),
            reportName: ensureString(result.reportName),
            reportUrl: ensureString(result.reportUrl),
        },
    }, { readerId });
};
const processCategories = async (visitor, result) => {
    const data = result.map((value) => ({
        name: ensureString(value.name),
        description: ensureString(value.description),
        descriptionHtml: ensureString(value.descriptionHtml),
        messageRegex: ensureString(value.messageRegex),
        traceRegex: ensureString(value.traceRegex),
        matchedStatuses: Array.isArray(value.matchedStatuses)
            ? value.matchedStatuses.map((v) => ensureString(v)).filter(notNull)
            : [],
        flaky: ensureBoolean(value.flaky),
    }));
    await visitor.visitMetadata({
        allure2_categories: data,
    }, { readerId });
};
const processEnvironmentXml = async (visitor, result) => {
    const { environment } = result;
    if (!isStringAnyRecord(environment)) {
        return;
    }
    const { parameter: parameters } = environment;
    if (!isStringAnyRecordArray(parameters)) {
        return;
    }
    const data = [];
    parameters.forEach((param) => {
        const { key, value } = param;
        const stringKey = ensureString(key);
        const stringValue = ensureString(value);
        if (stringKey && stringValue) {
            data.push({ name: stringKey, values: [stringValue] });
        }
    });
    await visitor.visitMetadata({
        allure_environment: data,
    }, {
        readerId,
    });
};
const processEnvironment = async (visitor, result) => {
    const data = Object.keys(result).map((key) => {
        const rawValue = result[key];
        const value = typeof rawValue === "string" ? rawValue : JSON.stringify(rawValue);
        return {
            name: key,
            values: [value],
        };
    });
    await visitor.visitMetadata({
        allure_environment: data,
    }, {
        readerId,
    });
};
const processFixtures = async (visitor, fixtures, type, children) => {
    if (fixtures) {
        for (const fixture of fixtures) {
            const dist = convertFixture(type, children, fixture);
            await visitor.visitTestFixtureResult(dist, {
                readerId,
                metadata: {
                    allure2_top_level_attachment_count: fixture?.attachments?.filter(notNull).length ?? 0,
                },
            });
        }
    }
};
const processTestResultContainer = async (visitor, result) => {
    if (result.children && result.children.length > 0) {
        await processFixtures(visitor, result.befores, "before", result.children);
        await processFixtures(visitor, result.afters, "after", result.children);
    }
};
const processGlobals = async (visitor, globals) => {
    const { attachments = [], errors = [] } = globals;
    const normalizedAttachments = Array.isArray(attachments) ? attachments : [];
    const normalizedErrors = isStringAnyRecordArray(errors) ? errors : [];
    const attachmentTimestamps = Object.fromEntries(normalizedAttachments
        .filter((attachment) => typeof attachment.timestamp === "number" && typeof attachment.source === "string")
        .map((attachment) => [attachment.source, attachment.timestamp]));
    const errorTimestamps = normalizedErrors.map((error) => ensureInt(error.timestamp));
    await visitor.visitMetadata({
        allure2_global_attachment_timestamps: attachmentTimestamps,
        allure2_global_error_timestamps: errorTimestamps,
    }, { readerId });
    await visitor.visitGlobals({
        attachments: normalizedAttachments.map((attachment) => convertGlobalAttachment(attachment)),
        errors: normalizedErrors.map((error) => convertGlobalError(error)),
    }, { readerId });
};
const convertCheckStatus = (status) => {
    return status === "passed" ? "passed" : "failed";
};
const convertStatus = (status) => {
    switch ((status ?? "unknown").toLowerCase()) {
        case "failed":
            return "failed";
        case "broken":
            return "broken";
        case "passed":
            return "passed";
        case "skipped":
            return "skipped";
        default:
            return "unknown";
    }
};
const convertFixture = (type, children, fixture) => {
    return {
        uuid: randomUUID(),
        testResults: children,
        type,
        name: fixture.name,
        start: ensureInt(fixture.start),
        stop: ensureInt(fixture.stop),
        status: convertStatus(fixture.status),
        message: ensureString(fixture?.statusDetails?.message),
        trace: ensureString(fixture?.statusDetails?.trace),
        steps: [
            ...(fixture?.steps?.filter(notNull)?.map(convertStep) ?? []),
            ...(fixture?.attachments?.filter(notNull)?.map(convertAttachment) ?? []),
        ],
    };
};
const convertStep = (step) => {
    const steps = step?.steps ?? [];
    const attachments = step?.attachments ?? [];
    if (steps.length === 0 && attachments.length === 1 && step.name === attachments[0].name) {
        return {
            ...convertAttachment(attachments[0]),
            start: step.start,
            stop: step.stop,
        };
    }
    return {
        name: ensureString(step.name),
        parameters: step?.parameters?.filter(notNull)?.map(convertParameter),
        status: convertStatus(step.status),
        message: ensureString(step?.statusDetails?.message),
        trace: ensureString(step?.statusDetails?.trace),
        steps: [
            ...(steps.filter(notNull)?.map(convertStep) ?? []),
            ...(attachments.filter(notNull)?.map(convertAttachment) ?? []),
        ],
        start: ensureInt(step.start),
        stop: ensureInt(step.stop),
        type: "step",
    };
};
const convertParameter = ({ mode, name, value, excluded }) => {
    return {
        name: ensureString(name),
        value: ensureString(value),
        excluded: ensureBoolean(excluded),
        hidden: mode === ParameterMode.HIDDEN,
        masked: mode === ParameterMode.MASKED,
    };
};
const convertAttachment = ({ name, type, source }) => {
    return {
        name: ensureString(name),
        contentType: ensureString(type),
        originalFileName: ensureString(source),
        type: "attachment",
    };
};
const convertGlobalAttachment = ({ environment, ...attachment }) => {
    return {
        ...convertAttachment(attachment),
        environment: ensureString(environment),
    };
};
const convertGlobalError = ({ environment, ...error }) => {
    return {
        message: ensureString(error.message),
        trace: ensureString(error.trace),
        expected: ensureString(error.expected),
        actual: ensureString(error.actual),
        environment: ensureString(environment),
    };
};
const convertLabel = ({ name, value }) => {
    return {
        name: ensureString(name),
        value: ensureString(value),
    };
};
const convertLink = ({ name, url, type }) => {
    return {
        name: ensureString(name),
        url: ensureString(url),
        type: ensureString(type),
    };
};
